 private String contactText(String value){return value.toLowerCase(java.util.Locale.ROOT).replace('ё','е').replaceAll("[^\\p{L}\\p{N}]+"," ").trim();}
 @JavascriptInterface public void findContacts(String query){if(query!=null&&query.trim().length()>=2&&query.length()<=80)findContactsV2("{\"first\":["+org.json.JSONObject.quote(query.trim())+"],\"remaining\":[]}");}
 @JavascriptInterface public void findContactsV2(String query){runOnUiThread(()->{if(!trusted(web.getUrl())||checkSelfPermission(Manifest.permission.READ_CONTACTS)!=PackageManager.PERMISSION_GRANTED||query==null||query.length()>500)return;try{org.json.JSONObject request=new org.json.JSONObject(query);org.json.JSONArray first=request.getJSONArray("first"),remaining=request.getJSONArray("remaining");if(first.length()<1||first.length()>8||remaining.length()>8)return;java.util.ArrayList<String> alternatives=new java.util.ArrayList<>(),required=new java.util.ArrayList<>();for(int i=0;i<first.length();i++){String term=contactText(first.getString(i));if(term.length()<2||term.length()>80)return;alternatives.add(term);}for(int i=0;i<remaining.length();i++){String term=contactText(remaining.getString(i));if(term.length()<2||term.length()>80)return;required.add(term);}java.util.ArrayList<String> names=new java.util.ArrayList<>(),ids=new java.util.ArrayList<>();try(Cursor cursor=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.CONTACT_ID,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME},null,null,ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME+" ASC")){int scanned=0;if(cursor!=null)while(cursor.moveToNext()&&scanned++<5000&&names.size()<30){String id=cursor.getString(0),name=cursor.getString(1);if(id==null||name==null||ids.contains(id))continue;String candidate=contactText(name);boolean matched=false;for(String term:alternatives)if(candidate.contains(term)){matched=true;break;}if(!matched)continue;for(String term:required){String stem=term.length()>=5&&term.matches(".*[уаеы]$")?term.substring(0,term.length()-1):term;if(!candidate.contains(term)&&!candidate.contains(stem)){matched=false;break;}}if(matched){ids.add(id);names.add(name);}}}if(names.isEmpty()){new AlertDialog.Builder(MainActivity.this).setMessage("Contact not found").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(MainActivity.this).setTitle("Choose a contact").setItems(names.toArray(new String[0]),(dialog,index)->showContactNumbers(ids.get(index),names.get(index))).setNegativeButton("Cancel",null).show();}catch(Exception ignored){}});}
 private void showContactNumbers(String id,String name){if(!trusted(web.getUrl())||checkSelfPermission(Manifest.permission.READ_CONTACTS)!=PackageManager.PERMISSION_GRANTED)return;java.util.ArrayList<String> numbers=new java.util.ArrayList<>(),labels=new java.util.ArrayList<>();try(Cursor cursor=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.NUMBER,ContactsContract.CommonDataKinds.Phone.TYPE,ContactsContract.CommonDataKinds.Phone.LABEL},ContactsContract.CommonDataKinds.Phone.CONTACT_ID+"=?",new String[]{id},null)){if(cursor!=null)while(cursor.moveToNext()&&numbers.size()<20){String number=cursor.getString(0);if(number!=null&&number.matches("[+0-9() .-]{3,40}")&&!numbers.contains(number)){numbers.add(number);labels.add(ContactsContract.CommonDataKinds.Phone.getTypeLabel(getResources(),cursor.getInt(1),cursor.getString(2))+" "+number);}}}catch(Exception ignored){}if(numbers.isEmpty())return;new AlertDialog.Builder(MainActivity.this).setTitle(name+" - choose a number").setItems(labels.toArray(new String[0]),(dialog,index)->openDialer(id,numbers.get(index))).setNegativeButton("Cancel",null).show();}
 @JavascriptInterface public void findApps(String query){runOnUiThread(()->{if(!trusted(web.getUrl())||query==null||query.trim().length()<2||query.length()>80)return;String needle=query.trim().toLowerCase(java.util.Locale.ROOT);Intent intent=new Intent(Intent.ACTION_MAIN);intent.addCategory(Intent.CATEGORY_LAUNCHER);java.util.ArrayList<String> names=new java.util.ArrayList<>(),packages=new java.util.ArrayList<>();for(android.content.pm.ResolveInfo info:getPackageManager().queryIntentActivities(intent,0)){try{String pkg=info.activityInfo.packageName,name=info.loadLabel(getPackageManager()).toString();if(pkg.equals(getPackageName())||!name.toLowerCase(java.util.Locale.ROOT).contains(needle)||packages.contains(pkg))continue;names.add(name);packages.add(pkg);if(names.size()>=30)break;}catch(Exception ignored){}}if(names.isEmpty()){new AlertDialog.Builder(MainActivity.this).setMessage("App not found").setPositiveButton("OK",null).show();return;}new AlertDialog.Builder(MainActivity.this).setTitle("Choose an app").setItems(names.toArray(new String[0]),(dialog,index)->launchApp(packages.get(index))).setNegativeButton("Cancel",null).show();});}
 private void openDialer(String contactId,String number){runOnUiThread(()->{if(!trusted(web.getUrl())||checkSelfPermission(Manifest.permission.READ_CONTACTS)!=PackageManager.PERMISSION_GRANTED||contactId==null||number==null||!number.matches("[+0-9() .-]{3,40}"))return;try(Cursor cursor=getContentResolver().query(ContactsContract.CommonDataKinds.Phone.CONTENT_URI,new String[]{ContactsContract.CommonDataKinds.Phone.CONTACT_ID,ContactsContract.CommonDataKinds.Phone.NUMBER},ContactsContract.CommonDataKinds.Phone.CONTACT_ID+"=?",new String[]{contactId},null)){boolean valid=false;if(cursor!=null)while(cursor.moveToNext()){if(number.equals(cursor.getString(1))){valid=true;break;}}if(!valid)return;new AlertDialog.Builder(MainActivity.this).setMessage("Open the dialer for " + number + "?").setNegativeButton("Cancel",null).setPositiveButton("Open",(dialog,which)->{if(trusted(web.getUrl())&&checkSelfPermission(Manifest.permission.READ_CONTACTS)==PackageManager.PERMISSION_GRANTED)try{startActivity(new Intent(Intent.ACTION_DIAL,Uri.fromParts("tel",number,null)));}catch(ActivityNotFoundException ignored){}}).show();}catch(Exception ignored){}});}
